queries.query:
// Scope mailbox data access for a confirmed compromised identity.
// [VERIFY in your workspace] Exchange mailbox column names in OfficeActivity are
// inconsistent across ingestion versions. Before trusting this, run:
//   OfficeActivity | getschema | where ColumnName has_any ('Logon','Client','Folder')
let lookback = 30d;
let victim   = 'jsmith@contoso.com';
OfficeActivity
| where TimeGenerated > ago(lookback)
| where RecordType == 'ExchangeItemAggregated'   // string member name, NOT the integer 50
| where Operation  == 'MailItemsAccessed'
| where MailboxOwnerUPN =~ victim
// Exchange records may append a port and wrap IPv6 in brackets: normalise before joining.
| extend ClientIPClean = extract(@'^\[?([0-9A-Fa-f:.]+)\]?(?::\d+)?$', 1, ClientIP)
| summarize
      Accesses   = count(),
      FirstSeen  = min(TimeGenerated),
      LastSeen   = max(TimeGenerated),
      Clients    = make_set(ClientInfoString, 20),
      LogonTypes = make_set(Logon_Type, 5)
    by ClientIPClean
| order by Accesses desc
